<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap/app.php';
$admin=pf_require_admin($pdo);$error='';$notice='';$syncId=0;$syncAction='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 pf_verify_csrf();$id=filter_var($_POST['campaign_id']??null,FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');
 if(!$id||!in_array($action,['pause','resume'],true))$error='Invalid campaign action.';
 else{$pdo->beginTransaction();try{
  $q=$pdo->prepare("SELECT c.id,c.campaign_type,c.status,c.reserved_budget,c.advertiser_id,c.ends_at,u.status user_status,p.status advertiser_status FROM pf_campaigns c JOIN users u ON u.id=c.advertiser_id JOIN pf_advertiser_profiles p ON p.user_id=c.advertiser_id WHERE c.id=? AND c.campaign_type IN ('SITE_DISPLAY','BLOG_SPONSORED') FOR UPDATE");$q->execute([$id]);$c=$q->fetch();if(!$c)throw new RuntimeException('Campaign not found.');
  if($action==='pause'){
   if($c['status']!=='ACTIVE')throw new RuntimeException('Only active campaigns can be paused.');
   $pdo->prepare("UPDATE pf_campaigns SET status='PAUSED' WHERE id=?")->execute([$id]);
   if($c['campaign_type']==='SITE_DISPLAY')$pdo->prepare("UPDATE pf_site_campaigns SET status='PAUSED' WHERE campaign_id=?")->execute([$id]);
   else{$pdo->prepare("UPDATE pf_blog_campaigns SET status='PAUSED',sync_status='PENDING' WHERE campaign_id=?")->execute([$id]);$syncId=$id;$syncAction='upsert';}
  }else{
   if($c['status']!=='PAUSED'||$c['user_status']!=='ACTIVE'||$c['advertiser_status']!=='ACTIVE')throw new RuntimeException('Only paused campaigns belonging to active advertisers can resume.');
   if($c['ends_at']!==null&&strtotime((string)$c['ends_at'])<time())throw new RuntimeException('This campaign has expired and cannot be resumed.');
   $childTable=$c['campaign_type']==='SITE_DISPLAY'?'pf_site_campaigns':'pf_blog_campaigns';$childCheck=$pdo->prepare("SELECT status FROM {$childTable} WHERE campaign_id=? FOR UPDATE");$childCheck->execute([$id]);if($childCheck->fetchColumn()!=='PAUSED')throw new RuntimeException('The campaign placement is not in a resumable paused state.');
   $table=$c['campaign_type']==='SITE_DISPLAY'?'pf_site_campaign_reservations':'pf_blog_campaign_reservations';
   $r=$pdo->prepare("SELECT amount FROM {$table} WHERE campaign_id=? AND status='RESERVED' FOR UPDATE");$r->execute([$id]);$amount=$r->fetchColumn();
   if($amount===false||(float)$amount<=0||abs((float)$amount-(float)$c['reserved_budget'])>0.01)throw new RuntimeException('The remaining campaign budget reservation does not match.');
   $pdo->prepare("UPDATE pf_campaigns SET status='ACTIVE' WHERE id=?")->execute([$id]);
   if($c['campaign_type']==='SITE_DISPLAY')$pdo->prepare("UPDATE pf_site_campaigns SET status='ACTIVE' WHERE campaign_id=?")->execute([$id]);
   else{$pdo->prepare("UPDATE pf_blog_campaigns SET status='ACTIVE',sync_status='PENDING',last_sync_error=NULL WHERE campaign_id=?")->execute([$id]);$syncId=$id;$syncAction='upsert';}
  }
  $pdo->prepare("INSERT INTO pf_audit_log(actor_user_id,action,subject_type,subject_id,after_json) VALUES (?,?,?,?,?)")->execute([(int)$admin['id'],'ADMIN_CAMPAIGN_'.$action,'CAMPAIGN',$id,json_encode(['action'=>$action,'campaign_type'=>$c['campaign_type']],JSON_THROW_ON_ERROR)]);
  $pdo->commit();$notice='Campaign status updated.';
  if($syncId){$sync=pf_sync_blog_campaign($pdo,$syncId,$syncAction);if($sync['ok'])$pdo->prepare("UPDATE pf_blog_campaigns SET sync_status='SYNCED',last_sync_error=NULL WHERE campaign_id=?")->execute([$syncId]);elseif($syncAction==='upsert'){$pdo->beginTransaction();$pdo->prepare("UPDATE pf_campaigns SET status='PAUSED' WHERE id=?")->execute([$syncId]);$pdo->prepare("UPDATE pf_blog_campaigns SET status='PAUSED',sync_status='FAILED',last_sync_error=? WHERE campaign_id=?")->execute([$sync['error'],$syncId]);$pdo->commit();pf_sync_blog_campaign($pdo,$syncId,'revoke');$error='Campaign was paused because blog synchronization failed.';}else{$pdo->prepare("UPDATE pf_blog_campaigns SET sync_status='FAILED',last_sync_error=? WHERE campaign_id=?")->execute([$sync['error'],$syncId]);$error='Campaign paused, but blog revoke synchronization failed.';}}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Campaign update failed.';}}
}
$rows=$pdo->query("SELECT c.id,c.title,c.campaign_type,c.status,c.currency,c.reserved_budget,c.starts_at,c.ends_at,u.name advertiser_name,p.status advertiser_status,sc.placement_key site_placement,bc.placement_key blog_placement,bc.sync_status,(SELECT COUNT(*) FROM pf_site_ad_events se WHERE se.campaign_id=c.id AND se.event_type='IMPRESSION')+(SELECT COUNT(*) FROM pf_blog_events be WHERE be.campaign_id=c.id AND be.event_type='IMPRESSION') impressions,(SELECT COUNT(*) FROM pf_site_ad_events sclick WHERE sclick.campaign_id=c.id AND sclick.event_type='CLICK')+(SELECT COUNT(*) FROM pf_blog_events bclick WHERE bclick.campaign_id=c.id AND bclick.event_type='CLICK') clicks FROM pf_campaigns c JOIN users u ON u.id=c.advertiser_id JOIN pf_advertiser_profiles p ON p.user_id=c.advertiser_id LEFT JOIN pf_site_campaigns sc ON sc.campaign_id=c.id LEFT JOIN pf_blog_campaigns bc ON bc.campaign_id=c.id WHERE c.campaign_type IN ('SITE_DISPLAY','BLOG_SPONSORED') ORDER BY FIELD(c.status,'PENDING_REVIEW','ACTIVE','PAUSED','DRAFT','COMPLETED','REJECTED'),c.created_at DESC LIMIT 300")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign management | PoketFlow</title><link rel="stylesheet" href="../assets/marketplace.css"><style>.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:11px;border-bottom:1px solid var(--line);white-space:nowrap}.inline{display:inline}</style></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="index.php">Admin home</a><a href="advertisers.php">Advertisers</a><a href="placements.php">Placements</a><a href="finance.php">Finance</a><a href="users.php">Members</a></nav></header><main class="container"><section class="welcome"><p class="eyebrow">CAMPAIGN CONTROL</p><h1>Manage advertising campaigns</h1><p class="muted">Pause and resume approved campaigns. Resuming requires an active advertiser and a matching reserved budget. Blog changes are synchronized with the separate blog application.</p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?><?php if($notice):?><div class="panel"><?=pf_e($notice)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Advertiser</th><th>Surface</th><th>Placement</th><th>Reserved</th><th>Impressions</th><th>Clicks</th><th>Schedule</th><th>Status</th><th>Blog sync</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=pf_e($r['title'])?><br><span class="small muted">#<?=(int)$r['id']?></span></td><td><?=pf_e($r['advertiser_name'])?><br><span class="small muted"><?=pf_e($r['advertiser_status'])?></span></td><td><?=$r['campaign_type']==='SITE_DISPLAY'?'Main site':'Blog'?></td><td><?=pf_e((string)($r['site_placement']??$r['blog_placement']??''))?></td><td><?=pf_e($r['currency'])?> <?=number_format((float)$r['reserved_budget'],2)?></td><td><?=number_format((int)$r['impressions'])?></td><td><?=number_format((int)$r['clicks'])?></td><td><?=pf_e(substr((string)$r['starts_at'],0,10))?> – <?=pf_e(substr((string)$r['ends_at'],0,10))?></td><td><?=pf_e($r['status'])?></td><td><?=pf_e((string)($r['sync_status']??'—'))?></td><td><?php if(in_array($r['status'],['ACTIVE','PAUSED'],true)):?><form class="inline" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="campaign_id" value="<?=(int)$r['id']?>"><button class="button small <?=$r['status']==='ACTIVE'?'danger':'primary'?>" name="action" value="<?=$r['status']==='ACTIVE'?'pause':'resume'?>"><?=$r['status']==='ACTIVE'?'Pause':'Resume'?></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="11">No advertising campaigns yet.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
